<script setup>
import "./styles.css";
import Icon from "./Icon.js";
const props = defineProps({ title: { type: String, default: "项目设置" }, description: { type: String, default: "" }, supporting: { type: String, default: "" }, lines: { type: Number, default: 1 }, leadingIcon: { type: String, default: "navigation/grid" }, trailing: { type: String, default: "text-arrow" }, trailingText: { type: String, default: "详情" }, disabled: Boolean });
const emit = defineEmits(["click"]);
const activate = (event) => { if (!props.disabled && (event.type === "click" || event.key === "Enter" || event.key === " ")) { event.preventDefault(); emit("click", event); } };
</script>
<template><div class="tui-component tui-item" role="button" :tabindex="props.disabled ? -1 : 0" data-component="item" data-logical-component="Item/Default" data-variant="default" :data-state="props.disabled ? 'disabled' : 'default'" :data-lines="props.lines" data-framework="vue" :aria-disabled="props.disabled || undefined" @click="activate" @keydown="activate"><span class="tui-item__leading" data-slot="leading"><Icon :name="props.leadingIcon" :size="24" /></span><span class="tui-item__content"><span data-slot="title" data-typography-role="body-l">{{ props.title }}</span><span v-if="props.description" data-slot="description" data-typography-role="body-m">{{ props.description }}</span><span v-if="props.supporting" data-slot="supporting" data-typography-role="caption-l">{{ props.supporting }}</span></span><span v-if="props.trailing === 'icon'" class="tui-item__trailing tui-item__trailing--icon" data-slot="trailing"><Icon name="action/more" :size="20" /></span><label v-else-if="props.trailing === 'radio'" class="tui-item__trailing tui-choice" data-slot="trailing" aria-label="已选中"><input type="radio" checked><span class="tui-radio__indicator" aria-hidden="true"></span></label><label v-else-if="props.trailing === 'checkbox'" class="tui-item__trailing tui-choice tui-checkbox" data-slot="trailing" aria-label="已选中"><input type="checkbox" checked><span class="tui-checkbox__indicator" aria-hidden="true"><Icon name="choice/check" :size="16" /></span></label><label v-else-if="props.trailing === 'switch'" class="tui-item__trailing tui-choice tui-switch" data-slot="trailing" aria-label="已开启"><input type="checkbox" role="switch" checked><span class="tui-switch__track" aria-hidden="true"></span></label><span v-else-if="props.trailing === 'notification-arrow'" class="tui-item__trailing tui-item__trailing--notification-arrow" data-slot="trailing"><span class="tui-item__notification-dot" aria-label="有新事件"></span><Icon name="navigation/chevron-right" :size="20" /></span><span v-else class="tui-item__trailing tui-item__trailing--text-arrow" data-slot="trailing" data-typography-role="body-m"><span>{{ props.trailingText }}</span><Icon name="navigation/chevron-right" :size="20" /></span></div></template>
